import{_ as t,l as i,o as e,c as s,v as r,p as l,x as o,d,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"货币危机模型","description":"","frontmatter":{"title":"货币危机模型","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/currency-crisis-models.md","filePath":"econ/currency-crisis-models.md","lastUpdated":1789023840000}'),p={name:"econ/currency-crisis-models.md"};function A(m,a,h,B,u,_){const n=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="货币危机模型" tabindex="-1">货币危机模型 <a class="header-anchor" href="#货币危机模型" aria-label="Permalink to &quot;货币危机模型&quot;">​</a></h1><div class="epigraph"><p>钉住与扩张性国内信贷不能共存：储备有限，影子浮动汇率一旦穿过钉住，投机者一次买完剩下的储备，危机是时间的函数，不是情绪的函数。</p><footer>—— Krugman, A Model of Balance-of-Payments Crises, JMCB 1979；Flood and Garber 1984</footer></div><p><a href="/econ/international-risk-sharing">上一课</a>写日常分担失败。本课缺口是坏状态：钉住崩溃。三代模型下一课把第一代放进谱系；本课先钉 Krugman 第一代的机制，接到主干<a href="/econ/sudden-stop">突然停止</a>与三角，不重画 IS–LM。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定 \\(E\\)、资本开放、国内信贷持续扩张（为财政赤字融资）。储备随信贷漏出。若永远钉住，储备终将负——不可能。Krugman：存在崩溃时点 \\(T\\)，使得影子汇率（储备耗尽后的浮动汇率）在 \\(T\\) 等于钉住；此前无攻击，此时投机者一次买光剩余储备。缺口不是「投资者恐慌」，而是套利：延迟攻击会留下跳升的资本利得，提前攻击会亏。危机日期由基本面路径唯一（在第一代）。</p><p><span class="marginnote">影子汇率：若今天就浮动、货币路径仍按信贷规则走，\\(E\\) 会在哪。Salant–Henderson 的黄金投机是祖先：政府以固定价卖有限库存。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>货币需求 \\(M/E=L(i,Y)\\)，钉住时 \\(E\\) 固定，\\(M\\) 由储备加国内信贷。信贷按常数增长。浮动后 \\(E\\) 随 \\(M\\) 走。平滑粘贴：崩溃瞬间 \\(E\\) 不跳（否则未利用套利）。解出 \\(T\\)。与三角：钉住 + 开放资本 ⇒ 货币不独立；硬要独立信贷，放弃的是钉住，形式是危机。</p>',8)),(e(),l(c,null,{default:o(()=>[E(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PEG%5B%22%E9%92%89%E4%BD%8F%20E%22%5D%20--%3E%20RES%5B%22%E5%82%A8%E5%A4%87%E7%BC%93%E5%86%B2%22%5D%0A%20%20CRED%5B%22%E6%8C%81%E7%BB%AD%E6%89%A9%E5%BC%A0%E4%BF%A1%E8%B4%B7%22%5D%20--%3E%20LEAK%5B%22%E5%82%A8%E5%A4%87%E6%BC%8F%E5%87%BA%22%5D%0A%20%20SHAD%5B%22%E5%BD%B1%E5%AD%90%20E%20%E5%8D%87%E7%A9%BF%E9%92%89%E4%BD%8F%22%5D%20--%3E%20ATT%5B%22%E4%B8%80%E6%AC%A1%E6%80%A7%E4%B9%B0%E5%85%89%E5%82%A8%E5%A4%87%22%5D%0A%20%20ATT%20--%3E%20FLOAT%5B%22%E8%A2%AB%E8%BF%AB%E6%B5%AE%E5%8A%A8%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与原罪：第一代可以在无错配下发生，对象是储备。原罪把贬值的净值成本加上，改变政府是否愿守——那是第三代味道，下一课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是有限库存加固定价格。与商品稳定储备同构。投机者不是非理性：他们在无利差时等待，在影子价格穿过时攻击。政策含义：要么停掉信贷扩张（财政 / 货币改革），要么提前浮动，要么资本管制（后课）拉长漏出时间。宣布「有足够储备」若信贷规则不变，只推迟 \\(T\\)。</p><p>与 UIP：第一代常在完美预见下写，没有 Fama 谜。加上不确定，攻击可以有随机时点，仍由基本面驱动，不是纯太阳黑子——太阳黑子是第二代。</p><p><span class="marginnote">Flood–Garber 把 Krugman 写成线性货币模型，便于课堂解 \\(T\\)。经验：拉丁美洲 1980 年代更像第一代；1992 年 ERM、1997 亚洲更要后两代。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有危机写成储备算术。经常账户可持续、银行、或有负债可以在储备仍多时崩溃——第二、三代。下一课专门分代。不要用本课写做空某货币的操作。量化栏外汇微观不是 \\(T\\) 的公式。</p><p>后课默认：第一代危机是不一致政策下的时机套利，影子汇率穿过钉住。三角被违反时，危机是形式之一。多重均衡与金融加速器留给三代课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>钉住 + 持续信贷扩张 ⇒ 储备有限，必破。</li><li>崩溃时点由影子汇率等于钉住决定；投机是套利。</li><li>改革规则或提前浮动，而不是口头「储备充足」。</li><li>无错配也可以有第一代危机。</li><li>出处：Krugman, <em>JMCB</em> 1979；Flood and Garber 1984；Salant–Henderson。</li></ul>',10))])}const D=t(p,[["render",A]]);export{f as __pageData,D as default};
